cat > /tmp/work/smdump.py <<'EOF'
import sys, os
sys.path.insert(0, '/app')
from modelgate.tfproto import saved_model_pb2
for d in sys.argv[1:]:
    print("=========", d)
    for root, dirs, files in os.walk(d):
        for f in files:
            p = os.path.join(root, f); print("  ", p, os.path.getsize(p))
    pb = os.path.join(d, 'saved_model.pb')
    if not os.path.exists(pb):
        pbt = os.path.join(d, 'saved_model.pbtxt')
        if os.path.exists(pbt):
            print("PBTXT:"); print(open(pbt).read()[:3000])
        continue
    sm = saved_model_pb2.SavedModel()
    sm.ParseFromString(open(pb,'rb').read())
    print("meta_graphs:", len(sm.meta_graphs))
    for mi, mg in enumerate(sm.meta_graphs):
        print(" mg", mi, "tags", list(mg.meta_info_def.tags))
        print("  signatures:", {k: (list(v.inputs.keys()), list(v.outputs.keys()), v.method_name) for k, v in mg.signature_def.items()})
        g = mg.graph_def
        print("  nodes:", [(n.name, n.op, list(n.input)) for n in g.node])
        for fn in g.library.function:
            print("  func", fn.signature.name, [(n.name, n.op, {k: (str(v)[:80]) for k, v in n.attr.items() if k=='f' or 'func' in k.lower() or k in ('then_branch','else_branch','body','cond','branches')}) for n in fn.node_def])
        for n in g.node:
            for k, v in n.attr.items():
                if v.HasField('func') or v.list.func:
                    print("  node", n.name, "attr", k, "->", v.func.name, [f.name for f in v.list.func])
EOF
