arguments.command:
cat > /tmp/work/arch.py <<'EOF'
import sys, zipfile, tarfile, gzip, io, pickletools, bz2, lzma
def dis(data, name):
    out = io.StringIO()
    try:
        pickletools.dis(data, out=out)
    except Exception as e:
        out.write(f"ERR {e}\n")
    lines = [l for l in out.getvalue().splitlines() if any(k in l for k in ("GLOBAL","REDUCE","BUILD","INST","OBJ","STOP","PROTO","ERR","highest","UNICODE","STRING","BYTES","PERSID"))]
    print(f"----- pickle {name}:"); print("\n".join(lines[:60]))
def handle(data, name, depth=0):
    ind = "  "*depth
    print(f"{ind}>> {name} ({len(data)} bytes) head={data[:8]!r}")
    if data[:2] == b'\x1f\x8b':
        # possibly multiple members
        d = gzip.decompress(data); handle(d, name+"|gz", depth+1); return
    if data[:3] == b'BZh':
        handle(bz2.decompress(data), name+"|bz2", depth+1); return
    if data[:6] == b'\xfd7zXZ\x00':
        handle(lzma.decompress(data), name+"|xz", depth+1); return
    if zipfile.is_zipfile(io.BytesIO(data)):
        zf = zipfile.ZipFile(io.BytesIO(data))
        for i in zf.infolist():
            print(f"{ind}  zip member {i.filename!r} size={i.file_size} comp={i.compress_type} hdr={i.header_offset} extra={i.extra!r}")
        for i in zf.infolist():
            if not i.filename.endswith('/'):
                handle(zf.read(i), name+"!"+i.filename, depth+1)
        return
    try:
        tf = tarfile.open(fileobj=io.BytesIO(data))
        ok = True
    except Exception:
        ok = False
    if ok:
        for m in tf.getmembers():
            print(f"{ind}  tar member {m.name!r} type={m.type!r} size={m.size}")
            if m.isfile():
                handle(tf.extractfile(m).read(), name+"!"+m.name, depth+1)
        return
    if data[:6] == b'\x93NUMPY':
        hl = int.from_bytes(data[8:10],'little') if data[6]==1 else int.from_bytes(data[8:12],'little')
        hdr_end = (10 if data[6]==1 else 12) + hl
        print(f"{ind}  npy header: {data[:hdr_end]!r}")
        handle(data[hdr_end:], name+"|npydata", depth+1); return
    if data[:1] in (b'\x80', b'(', b'c', b'}', b']', b'N', b'I', b'V', b'S', b'U', b'K') :
        dis(data, name); return
    if data[:4] == b'\x89HDF':
        print(f"{ind}  HDF5 file"); return
    print(f"{ind}  text? {data[:200]!r}")
for p in sys.argv[1:]:
    print("=========", p)
    handle(open(p,'rb').read(), p)
EOF
