cat > /tmp/work/keras.py <<'EOF'
import sys, json, zipfile, io, h5py
for p in sys.argv[1:]:
    print("=========", p)
    if p.endswith('.h5'):
        with h5py.File(p, 'r') as f:
            print("root attrs:", {k: (type(v).__name__, len(v) if hasattr(v,'__len__') else v) for k, v in f.attrs.items()})
            raw = f.attrs.get('model_config')
            if isinstance(raw, bytes): raw = raw.decode()
            print(json.dumps(json.loads(raw), indent=1)[:6000])
            def visit(name, obj):
                print("   ", name, dict(obj.attrs) if len(obj.attrs) < 6 else list(obj.attrs.keys()))
            f.visititems(visit)
    else:
        zf = zipfile.ZipFile(p)
        for i in zf.infolist(): print("  member", i.filename, i.file_size, i.compress_type)
        print(json.dumps(json.loads(zf.read('config.json')), indent=1)[:6000])
        print("metadata:", zf.read('metadata.json'))
EOF
