        return OPAQUE
    if tkind == "attrgetter":
        names = [c for c in (_concrete(a) for a in args) if isinstance(c, str)]
        return V("attrgetter", names=names) if names else OPAQUE
    if tkind == "methodcaller":
        if args:
            nm = _concrete(args[0])
            if isinstance(nm, str):
