    return OPAQUE


def _consume(args, ctx):
    for a in args:
        if a.kind == "lazymap":
            _invoke(a.func, [OPAQUE], ctx)


def _resolve_dotted(s, ctx):
    s = s.replace(":", ".")
    parts = s.split(".")
    if not parts:
        return OPAQUE
    cur = V("ref", path=policy.normalize_path(parts[0]))
    for p in parts[1:]:
        cur = _resolve_attr(cur, p, ctx)
    return cur


def _resolve_attr(obj, name, ctx):
    if "." in name:
        cur = obj
        for p in name.split("."):
            cur = _resolve_attr(cur, p, ctx)
        return cur
    base = None
