import json, os, random, subprocess, sys, tempfile, time, glob

cli = "/app/modelgate/cli.py"
KINDS = {"code-execution", "process", "file-access", "network", "unsupported"}
random.seed(1234)

seeds = []
for base in ["/app/samples", "/tmp/corpus"]:
    for p in glob.glob(os.path.join(base, "*")):
        if os.path.isfile(p) and not p.endswith("labels.json"):
            seeds.append(open(p, "rb").read())

cases = []
# mutated seeds
for s in seeds:
    for _ in range(3):
        b = bytearray(s)
        for _ in range(random.randint(1, 20)):
            if not b:
                break
            b[random.randrange(len(b))] = random.randrange(256)
        cases.append(bytes(b))
    cases.append(s[:random.randint(0, len(s))])  # truncations
# pure random
for _ in range(40):
    cases.append(bytes(random.randrange(256) for _ in range(random.randint(0, 400))))
# pickle-ish random (start with PROTO)
for _ in range(40):
    cases.append(b"\x80\x04" + bytes(random.randrange(256) for _ in range(random.randint(0, 300))))

bad = 0
slow = 0.0
for i, data in enumerate(cases):
    with tempfile.TemporaryDirectory() as tmp:
        art = os.path.join(tmp, f"a{i}.bin")
        open(art, "wb").write(data)
        rep = os.path.join(tmp, "r.json")
        t = time.monotonic()
        try:
            proc = subprocess.run([sys.executable, "-I", cli, "scan", "--output", rep, art],
                                  cwd=tmp, capture_output=True, text=True, timeout=60)
        except subprocess.TimeoutExpired:
            print("TIMEOUT case", i); bad += 1; continue
        slow = max(slow, time.monotonic() - t)
        if proc.returncode != 0:
            print("NONZERO exit", i, proc.stderr[-150:]); bad += 1; continue
        try:
            doc = json.load(open(rep))
            e = doc["results"][0]
            assert e["path"] == art
            assert e["verdict"] in ("malicious", "clean")
            assert (e["verdict"] == "malicious") == (len(e["findings"]) > 0)
            for f in e["findings"]:
                assert set(f) == {"kind", "location", "detail"}
                assert f["kind"] in KINDS
                assert all(isinstance(f[k], str) for k in f)
        except Exception as ex:
            print("BADREPORT", i, ex, proc.stderr[-150:]); bad += 1

print(f"fuzz cases={len(cases)} bad={bad} slowest={slow:.2f}s")

